#!/usr/bin/env python3
"""
install_stage6c.py - puts the Stage 6b Meta simulator in place as test_stage6_meta_sim.py, whatever the downloaded file is called.

HOW (one step, from the cf-worker folder):
    cd /workspaces/boltane-workers-poc/files12/cf-worker
    python install_stage6c.py

Creates (or replaces) test_stage6_meta_sim.py only. Nothing else is touched. The embedded file carries a SHA-256 that is
checked after writing, and the result is compile-checked.
"""
import base64, hashlib, py_compile, sys, zlib
from pathlib import Path

NAME = "test_stage6_meta_sim.py"
SHA = "c99d7eee8e7c20c9663f651201b266558106c628c2717f9da36dbb9f2349b92f"
DATA = ""

root = Path.cwd()
if not (root / "wrangler.jsonc").exists() or not (root / "test_stage5_firewall.py").exists():
    sys.exit("This does not look like the cf-worker folder (wrangler.jsonc and test_stage5_firewall.py not found here).\n"
             "Run:  cd /workspaces/boltane-workers-poc/files12/cf-worker   and try again.")
raw = zlib.decompress(base64.b64decode(DATA))
if hashlib.sha256(raw).hexdigest() != SHA:
    sys.exit("embedded data is corrupted (hash mismatch) - download install_stage6c.py again")
target = root / NAME
existed = target.exists()
target.write_bytes(raw)
try:
    py_compile.compile(str(target), doraise=True, cfile="/tmp/_stage6c_check.pyc")
except py_compile.PyCompileError as exc:
    sys.exit(f"FAIL  {NAME} does not compile: {exc}")
print(f"{'REPLACED' if existed else 'CREATED '}  {NAME}   sha256={SHA[:12]}...  compiles")
print("\nDone. Next:  python test_stage6_meta_sim.py")
